using Xunit;
using Xunit.Abstractions;

namespace Neemle.OrmLite.Tests.OrmLiteGolden;

// QA ORML-156 probe: mutant battery against GeneratedCodeEquivalence.
public sealed class QaEquivalenceProbeTests(ITestOutputHelper output)
{
    private const string Base = """"
// <auto-generated/>
#nullable enable
#pragma warning disable CS1591
namespace N
{
    /// <summary>Doc text.</summary>
    [System.Obsolete("x")]
    public sealed partial class C<T>
    {
        private readonly string? _s = "abc";
        public int A(int x) => x + 1;
        public long B() => 10L;
        public char Ch() => 'a';
        public string Raw() => """raw text""";
        public System.ReadOnlySpan<byte> U() => "u8 text"u8;
        public string I(int x) => $"v={x:N2}";
        public string V { get; set { _ = value; } }
        public System.Func<int, int> L() => e => e;
#if NEVER_DEFINED
        public int Hidden() => 1;
#endif
        public int Z() => 0;
    }
}
"""";

    public static TheoryData<string, string, string, bool> Cases()
    {
        var d = new TheoryData<string, string, string, bool>();
        void M(string name, string from, string to, bool equivalent) => d.Add(name, from, to, equivalent);
        M("identifier", "public int A(int x) => x + 1;", "public int A(int y) => y + 1;", false);
        M("operator", "x + 1", "x - 1", false);
        M("numeric literal", "x + 1", "x + 2", false);
        M("numeric suffix", "10L", "10", false);
        M("char literal", "'a'", "'b'", false);
        M("string literal content", "\"abc\"", "\"abd\"", false);
        M("string escape vs verbatim same value", "\"abc\"", "@\"abc\"", false);
        M("raw string content", "\"\"\"raw text\"\"\"", "\"\"\"raw texT\"\"\"", false);
        M("utf8 string content", "\"u8 text\"u8", "\"u8 texT\"u8", false);
        M("interpolated format", "{x:N2}", "{x:N3}", false);
        M("modifier", "public sealed partial class", "public partial class", false);
        M("modifier readonly", "private readonly string?", "private string?", false);
        M("attribute removed", "[System.Obsolete(\"x\")]\n", "", false);
        M("attribute argument", "Obsolete(\"x\")", "Obsolete(\"y\")", false);
        M("generic arity", "class C<T>", "class C<T, U>", false);
        M("nullability annotation", "string? _s", "string _s", false);
        M("pragma", "#pragma warning disable CS1591", "#pragma warning disable CS1592", false);
        M("nullable directive", "#nullable enable", "#nullable disable", false);
        M("nullable directive dropped", "#nullable enable\n", "", false);
        M("doc comment", "Doc text.", "Doc texts.", false);
        M("disabled #if text", "Hidden() => 1;", "Hidden() => 2;", false);
        M("member order", "        public long B() => 10L;\n        public char Ch() => 'a';\n", "        public char Ch() => 'a';\n        public long B() => 10L;\n", false);
        M("lambda parens", "e => e;", "(e) => e;", false);
        M("verbatim contextual value", "_ = value;", "_ = @value;", true);
        M("verbatim plain identifier", "public int Z()", "public int @Z()", true);
        M("reindent + blank lines", "        public int Z() => 0;", "\n\n\t\t\tpublic   int Z ( )=>0 ;", true);
        M("trailing whitespace in comment", "// <auto-generated/>", "//   <auto-generated/>   ", true);
        M("comment spacing after slashes", "// <auto-generated/>", "//<auto-generated/>", true);
        M("doc comment rewrapped", "/// <summary>Doc text.</summary>", "/// <summary>Doc\n    /// text.</summary>", true);
        return d;
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Probe(string name, string from, string to, bool expectEquivalent)
    {
        var src = Base.Replace("\r\n", "\n");
        Assert.True(src.Contains(from, StringComparison.Ordinal), name + ": base lacks " + from);
        var at = src.IndexOf(from, StringComparison.Ordinal);
        var mutant = src[..at] + to + src[(at + from.Length)..];
        var diff = GeneratedCodeEquivalence.Difference(src, mutant);
        output.WriteLine($"PROBE [{name}] expectEquivalent={expectEquivalent} got={(diff is null ? "EQUIVALENT" : "DIFFERENT: " + diff)}");
        Assert.Equal(expectEquivalent, diff is null);
    }

    [Fact]
    public void Base_parses_and_is_self_equivalent() => Assert.Null(GeneratedCodeEquivalence.Difference(Base, Base.Replace("\n", "\r\n")));
}
